func _craft_build_preview() -> void:
	if m.craft_fishbox == null:
		return
	for child: Node in m.craft_fishbox.get_children():
		child.queue_free()
	var layers: Array = m.CREATURE_LAYERS.get(m.craft_kind, m.CREATURE_LAYERS["fish"])
	var order := [String(layers[1]), String(layers[0]), String(layers[2])]
	var roles := ["body", "accent", "line"]
	var colors := [m.craft_body, Color(m.craft_fins.r, m.craft_fins.g, m.craft_fins.b, 1.0), Color.WHITE]
	var rainbows := [m.craft_body_rb, m.craft_fins_rb, false]
	for i in range(3):
		var texture_rect := TextureRect.new()
		texture_rect.texture = load("res://assets/mg/" + order[i] + ".png")
		texture_rect.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
		texture_rect.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_CENTERED
		texture_rect.size = m.craft_fishbox.size
		texture_rect.modulate = colors[i]
		texture_rect.mouse_filter = Control.MOUSE_FILTER_IGNORE
		texture_rect.set_meta("role", roles[i])
		m.craft_fishbox.add_child(texture_rect)
		if roles[i] != "line":
			m._layer_fx(texture_rect, roles[i], colors[i], rainbows[i], m.craft_kind)

func _make_creature_node(kind: String, body: Color, accent: Color, body_rb: bool = false, acc_rb: bool = false, third: Color = Color(0, 0, 0, 0)) -> Node3D:
	if CRAFT_RIGGED.has(kind):
		var rspec: Array = CRAFT_RIGGED[kind]
		var c3: Color = third if third.a > 0.0 else (rspec[2] as Color)
		var rn := _gen2_creature_rigged(String(rspec[0]), float(rspec[1]), body, accent, c3)
		if rn != null:
			if body_rb or acc_rb:
				rn.tree_entered.connect(_start_gen2_rainbow.bind(rn, body_rb, acc_rb), CONNECT_ONE_SHOT)
			return rn
	if CRAFT_GEN2.has(kind):
		var spec: Array = CRAFT_GEN2[kind]
		var pf := _gen2_creature(String(spec[0]), Vector3.ZERO, float(spec[1]))
		if pf != null:
			remove_child(pf)   # _gen2_prop parents to main; callers re-parent
			for mi in _all_meshes(pf):
				var mesh: Mesh = mi.mesh
				if mesh == null:
					continue
				for si in range(mesh.get_surface_count()):
					var sm2: Material = mi.get_surface_override_material(si)
					if sm2 is ShaderMaterial:
						(sm2 as ShaderMaterial).set_shader_parameter("paint_mix", 1.0)
						(sm2 as ShaderMaterial).set_shader_parameter("paint_body", body)
						(sm2 as ShaderMaterial).set_shader_parameter("paint_fin", accent)
			pf.set_meta("gen2", true)   # base at origin (billboards are center-origin)
			if body_rb or acc_rb:
				pf.tree_entered.connect(_start_gen2_rainbow.bind(pf, body_rb, acc_rb), CONNECT_ONE_SHOT)
			return pf
	var ln: Array = CREATURE_LAYERS.get(kind, CREATURE_LAYERS["fish"])
	var root := Node3D.new()
	# inner pivot so the idle animation never fights whoever owns root position
	var anim := Node3D.new()
	root.add_child(anim)
	var lb := Sprite3D.new()
	lb.texture = load("res://assets/mg/" + String(ln[1]) + ".png")
	lb.billboard = BaseMaterial3D.BILLBOARD_ENABLED; lb.pixel_size = 0.02; lb.render_priority = 0
	anim.add_child(lb)
	var la := Sprite3D.new()
	la.texture = load("res://assets/mg/" + String(ln[0]) + ".png")
	la.billboard = BaseMaterial3D.BILLBOARD_ENABLED; la.pixel_size = 0.02; la.render_priority = 1
	anim.add_child(la)
	var ll := Sprite3D.new()
	ll.texture = load("res://assets/mg/" + String(ln[2]) + ".png")
	ll.billboard = BaseMaterial3D.BILLBOARD_ENABLED; ll.pixel_size = 0.02; ll.render_priority = 2
	anim.add_child(ll)
	# colors + idle tweens can only start inside the tree, hence the deferred
	# hook (create_tween() errors outside it; this also restores the craft
	# tints the billboard fallback would otherwise render pure white)
	root.tree_entered.connect(_creature_spawned.bind(lb, la, anim, body, accent, body_rb, acc_rb, kind), CONNECT_ONE_SHOT)
	return root

func _stuffie_cutout(d: Dictionary, c: Array[Color], target_height: float) -> Node3D:
	# Stuffies are deliberately flat storybook cutouts. This replaces the
	# retired GLB path for the follower, battle copy, and Studio display.
	var root := Node3D.new()
	root.name = "StuffieCutout_" + String(d.get("id", "friend"))
	var anim := Node3D.new()
	anim.name = "StorybookBob"
	root.add_child(anim)
	if d.has("sprite"):
		var direct_tex: Texture2D = load(FashionOutfitRenderer.path(m, String(d["sprite"])))
		if direct_tex == null:
			return null
		var direct := Sprite3D.new()
		direct.name = "StorybookSprite"
		direct.texture = direct_tex
		direct.billboard = BaseMaterial3D.BILLBOARD_ENABLED
		direct.pixel_size = target_height / maxf(float(direct_tex.get_height()), 1.0)
		direct.render_priority = 2
		anim.add_child(direct)
	else:
		var kind := String(d.get("kind", ""))
		if not m.CREATURE_LAYERS.has(kind):
			return null
		var layer_names: Array = m.CREATURE_LAYERS[kind]
		var body_tex: Texture2D = load("res://assets/mg/" + String(layer_names[1]) + ".png")
		if body_tex == null:
			return null
		var pixel: float = target_height / maxf(float(body_tex.get_height()), 1.0)
		var draw_order: Array = [1, 0, 2]
		var tints: Array[Color] = [c[0], c[1], Color.WHITE]
		for i in range(draw_order.size()):
			var layer_index: int = int(draw_order[i])
			var tex: Texture2D = load("res://assets/mg/" + String(layer_names[layer_index]) + ".png")
			if tex == null:
				continue
			var layer := Sprite3D.new()
			layer.name = "StorybookLayer_%d" % i
			layer.texture = tex
			layer.billboard = BaseMaterial3D.BILLBOARD_ENABLED
			layer.pixel_size = pixel
			layer.render_priority = i
			layer.modulate = tints[i]
			anim.add_child(layer)
	root.set_meta("storybook_sprite", true)
	return root

